import re


_UNIT_SECONDS = {"h": 3600, "m": 60, "s": 1}


def parse_duration(text):
    if not isinstance(text, str):
        raise ValueError(text)
    text = text.strip()
    if not text:
        raise ValueError(text)
    total = 0
    pos = 0
    for match in re.finditer(r"(\d+)([hms])", text):
        if match.start() != pos:
            raise ValueError(text)
        total += int(match.group(1)) * _UNIT_SECONDS[match.group(2)]
        pos = match.end()
    if pos != len(text):
        raise ValueError(text)
    return total

