import re
from fractions import Fraction

_PATTERN = re.compile(r'^(?:(\d+(?:\.\d+)?)h)?(?:(\d+(?:\.\d+)?)m)?(?:(\d+(?:\.\d+)?)s)?$', re.IGNORECASE)


def parse_duration(text):
    if not isinstance(text, str):
        raise ValueError("duration must be a string")
    m = _PATTERN.fullmatch(text.strip())
    if not m or all(g is None for g in m.groups()):
        raise ValueError(f"invalid duration: {text!r}")
    h, mi, s = (Fraction(g) if g is not None else Fraction(0) for g in m.groups())
    total = h * 3600 + mi * 60 + s
    if total.denominator != 1:
        raise ValueError(f"duration is not a whole number of seconds: {text!r}")
    return int(total)


def format_duration(seconds):
    if not isinstance(seconds, int) or isinstance(seconds, bool):
        raise ValueError("seconds must be an int")
    if seconds < 0:
        raise ValueError("seconds must be non-negative")
    if seconds == 0:
        return "0s"
    h, rem = divmod(seconds, 3600)
    m, s = divmod(rem, 60)
    parts = []
    if h:
        parts.append(f"{h}h")
    if m:
        parts.append(f"{m}m")
    if s:
        parts.append(f"{s}s")
    return "".join(parts)

import sys

from durations import format_duration, parse_duration


def main() -> int:
    total = 0
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        try:
            total += parse_duration(line)
        except (ValueError, TypeError) as exc:
            print(f"invalid duration: {line!r}: {exc}", file=sys.stderr)
            return 1
    print(format_duration(total))
    return 0


if __name__ == "__main__":
    sys.exit(main())

